    mov rax, [rel _last_error]
    test rax, rax
    jz .skip_error_25  ; skip if no error
    PRINT_STR str_78, str_78_len
    PRINT_NEWLINE
    ; exit program
    mov rax, 1
    mov rdi, rax  ; exit code
    push rdi      ; save exit code
    call _cleanup_all
    pop rdi       ; restore exit code
    EXIT rdi
    CLEAR_LAST_ERROR
.skip_error_25:

    ; Cleanup all resources before exit
    call _cleanup_all

    ; Exit program
    EXIT 0
